  {
    "id": "340099111",
    "title": "14. Email & Notification Configuration",
    "type": "page",
    "created": "",
    "updated": "",
    "url": "https://zimmermannworkboard.atlassian.net/wiki/spaces/SFCC/pages/340099111",
